//! Range measurement anchor node
//!
//! This is an anchor node used for range measurement. Anchors have a known
//! location, and provide the support infrastructure requires by tag nodes to
//! determine their own distance from the available anchors.
//!
//! Currently, distance measurements have a highly inaccurate result. One reason
//! that could account for this is the lack of antenna delay calibration, but
//! it's possible that there are various hidden bugs that contribute to this.

#![allow(dead_code)]
#![no_main]
#![no_std]

mod peripherals;

use embassy_executor::Spawner;
use embassy_time::Timer;
// Print panic message to probe console
use {defmt_rtt as _, panic_probe as _};

use embassy_stm32::{bind_interrupts, gpio::{Level, Output, Speed}, usb, Config};
use embassy_stm32::exti::ExtiInput;
use embassy_stm32::gpio::Pull;
use embassy_stm32::peripherals::USB;
use embassy_usb::class::cdc_acm::State;
use crate::peripherals::bootstrap::{BootstrapDevice, STM6600BootstrapDevice};
use crate::peripherals::usb_debug;

bind_interrupts!(struct Irqs {
    USB => usb::InterruptHandler<USB>;
});

#[embassy_executor::main]
async fn main(spawner: Spawner) {
    defmt::info!("Launching anchor");

    let p = embassy_stm32::init(Config::default());

    // Initialize native USB CDC for debugging
    static USB_STATE: static_cell::StaticCell<State> = static_cell::StaticCell::new();
    let driver = usb::Driver::new(p.USB, Irqs, p.PA12, p.PA11);
    let usb_state = USB_STATE.init(State::new());

    spawner.spawn(usb_task(driver, usb_state)).unwrap();

    let mut charger_enable = Output::new(p.PA10, Level::Low, Speed::Low);
    let mut charger_en1 = Output::new(p.PB0, Level::Low, Speed::Low);
    let mut charger_en2 = Output::new(p.PB1, Level::Low, Speed::Low);

    // Bootstrap the STM6600 power management IC
    let power_int = ExtiInput::new(p.PB7, p.EXTI7, Pull::Up);
    let ps_hold = Output::new(p.PB5, Level::Low, Speed::Low);
    let mut bootstrap = STM6600BootstrapDevice::new(power_int, ps_hold);
    bootstrap.initialize().await.expect("Can't initialize bootstrap");

    // Initialize Battery Monitor
    // let adc = Adc::new(p.ADC1);
    // let battery_read_pin: Peri<PA3> = p.PA3;
    // let mut battery_monitor = SingleCellLiIonBatteryMonitor::new(adc, battery_read_pin);
    // let fist_voltage = battery_monitor.read_voltage_mv().await.expect("Can't read Voltage");
    // let fist_percentage = battery_monitor.read_percentage().await.expect("Can't read Percentage");
    // defmt::info!("Battery monitor initialized with voltage: {} mV -- {}", fist_voltage, fist_percentage);

    // Initialize Indicator Led
    let mut orange_pin = Output::new(p.PA8, Level::Low, Speed::Low);
    let mut green_pin = Output::new(p.PA9, Level::Low, Speed::Low);
    // let mut indicator_led = LtstIndicatorLed::new(orange_pin, green_pin);
    // indicator_led.show_battery_percentage(fist_percentage).expect("Can't set initial LED state");

    orange_pin.set_high();
    green_pin.set_high();

    charger_enable.set_low();

    // Set recharge current to 500mA
    charger_en1.set_high();
    charger_en2.set_low();

    usb_println!("UWB Anchor Initialized");
    usb_println!("System ready for debugging via USB");

    let mut counter = 0u32;
    loop {
        Timer::after_millis(1000).await;
        usb_println!("Heartbeat: {}", counter);
        counter = counter.wrapping_add(1);
    }
}

#[embassy_executor::task]
async fn usb_task(driver: usb::Driver<'static, USB>, state: &'static mut State<'static>) {
    usb_debug::usb_task(driver, state).await;
}

use embassy_stm32::usb::{Driver, Instance};
use embassy_usb::class::cdc_acm::{CdcAcmClass, State};
use embassy_usb::{Builder, Config};
use embassy_sync::blocking_mutex::raw::ThreadModeRawMutex;
use embassy_sync::channel::Channel;
use embassy_futures::select::{select, Either};

pub static USB_CHANNEL: Channel<ThreadModeRawMutex, heapless::String<256>, 16> = Channel::new();

pub fn create_usb_config() -> Config<'static> {
    let mut config = Config::new(0x16c0, 0x27dd);
    config.manufacturer = Some("Emerge");
    config.product = Some("UWB Anchor");
    config.serial_number = Some("12345678");
    config.max_power = 100;
    config.max_packet_size_0 = 64;

    config
}

pub async fn usb_task<'d, T: Instance + 'd>(
    driver: Driver<'d, T>,
    state: &'static mut State<'static>,
) {
    let config = create_usb_config();

    static DEVICE_DESCRIPTOR: static_cell::StaticCell<[u8; 256]> = static_cell::StaticCell::new();
    static CONFIG_DESCRIPTOR: static_cell::StaticCell<[u8; 256]> = static_cell::StaticCell::new();
    static BOS_DESCRIPTOR: static_cell::StaticCell<[u8; 256]> = static_cell::StaticCell::new();
    static CONTROL_BUF: static_cell::StaticCell<[u8; 128]> = static_cell::StaticCell::new();

    let mut builder = Builder::new(
        driver,
        config,
        DEVICE_DESCRIPTOR.init([0; 256]),
        CONFIG_DESCRIPTOR.init([0; 256]),
        BOS_DESCRIPTOR.init([0; 256]),
        &mut [],
        CONTROL_BUF.init([0; 128]),
    );

    let mut class = CdcAcmClass::new(&mut builder, state, 64);
    let mut usb = builder.build();

    loop {
        let run_fut = usb.run();
        let class_fut = async {
            loop {
                class.wait_connection().await;
                defmt::info!("USB connected");

                loop {
                    let data = USB_CHANNEL.receive().await;
                    let bytes = data.as_bytes();
                    match class.write_packet(bytes).await {
                        Ok(_) => {}
                        Err(e) => {
                            defmt::warn!("USB write error: {:?}", e);
                            break;
                        }
                    }
                }
            }
        };

        match select(run_fut, class_fut).await {
            Either::First(_) => {}
            Either::Second(_) => {}
        }
    }
}

#[macro_export]
macro_rules! usb_println {
    ($($arg:tt)*) => {{
        use core::fmt::Write;
        let mut buf = heapless::String::<256>::new();
        let _ = write!(buf, $($arg)*);
        let _ = write!(buf, "\r\n");
        $crate::peripherals::usb_debug::USB_CHANNEL.try_send(buf).ok();
    }};
}
